For a sequence~$\mathbf{c}=(c_1,\ldots,c_n)$, define a \emph{synchronization vector}~$\mathbbold{1}_{sync}(\mathbf{c})\in\{0,1\}^n$ by
\begin{align*}
\mathbbold{1}_{sync}(\mathbf{c})_i &= \begin{cases}
1, &\text{if~$(c_{i-3k+1},c_{i-3k+2},\ldots,c_{i+\lceil \log k\rceil +4})$ is a \emph{synchronization pattern},}\\
0,&\text{else.}\\
\end{cases}
\end{align*}

Define the integer vectors
\begin{align*}
    \mathbf{m}^{(\ell)}\triangleq (1^\ell,1^\ell+2^\ell,\ldots,\sum^n_{j=1}j^\ell)
\end{align*}
for~$\ell\in [0,\ldots,6k]$, where the~$i$-th entry of~$\mathbf{m}^{(\ell)}$ is the sum of the~$\ell$-th powers of the first~$i$ entries.

For an integer vector~$\mathbf{v}=(v_0,\ldots,v_{6k})$ that satisfies~$0\le v_e< 3kn^{e+1}$,~$e\in [0,6k]$, 
let
\begin{align} M(\mathbf{v})= \sum^{6k}_{e=0}v_e\prod^{e-1}_{i=0}3kn^{i+1}
\end{align}
be a one-to-one mapping that maps the vector~$\mathbf{v}$ into an integer~$M(\mathbf{v})\in[0,(3k)^{6k+1}n^{(3k+1)(6k+1)}-1]$.

A sequence~$\mathbf{c}\in\{0,1\}^n$ is said to be~\emph{$k$ dense} if the lengths of the~$0$ runs in~$\mathbbold{1}_{sync}(\mathbf{c})$ is at most~
\begin{align*}
L\triangleq (\lceil \log k\rceil+5)2^{\lceil \log k\rceil+9}\lceil \log n \rceil
+ (3k+\lceil \log k\rceil+4)(\lceil \log n\rceil +9+\lceil\log k\rceil).
\end{align*}

A\boldsymbol{x}=\begin{bmatrix}
\sum^{p_{1}}_{i=p_{0}+1}|s_i|i^0 &\ldots & \sum^{p_{6k+1}}_{i=p_{6k}+1}|s_i|i^0\\
\vdots &\ddots & \vdots\\
\sum^{p_{1}}_{i=p_{0}+1}|s_i|i^{6k} &\ldots & \sum^{p_{6k+1}}_{i=p_{6k}+1}|s_i|i^{6k}
\end{bmatrix}
\begin{bmatrix}
x_0\\
\vdots\\
x_{6k}\\
\end{bmatrix}
=0

B\boldsymbol{x}'=\begin{bmatrix}
\sum^{p_{j_1}}_{i=p_{j_1-1}+1}|s_i|i^0 &\ldots & \sum^{p_{j_Q}}_{i=p_{j_{Q-1}}+1}|s_i|i^0\\
\vdots &\ddots & \vdots\\
\sum^{p_{j_1}}_{i=p_{j_1-1}+1}|s_i|i^{Q-1} &\ldots & \sum^{p_{j_Q}}_{i=p_{j_{Q-1}}+1}|s_i|i^{Q-1}
\end{bmatrix}
\begin{bmatrix}
x_0\\
\vdots\\
x_{Q-1}\\
\end{bmatrix}
=0

We are now ready to prove Lemma~\ref{lemma:protectingpattern}.
We have shown in Lemma~\ref{lemma:syncvector} that~$f(\mathbbold{1}_{sync}(\mathbf{c}))\ne f(\mathbbold{1}_{sync}(\mathbf{c}'))$ for~$\mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}$. Hence
\newline$|M(f(\mathbbold{1}_{sync}(\mathbf{c})))-M(f(\mathbbold{1}_{sync}(\mathbf{c}')))|\ne 0$ (recall Eq.~\eqref{equation:Mfunction} for definition of function~$M(\mathbf{v})$) for~$\mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}$.
According to Lemma~\ref{lemma:numberofdivisors}, the number of divisors of~$|M(f(\mathbbold{1}_{sync}(\mathbf{c})))-M(f(\mathbbold{1}_{sync}(\mathbf{c}')))|$ is upper bounded by
\begin{align*}
2^{2[(3k+1)(6k+1)\ln n+(6k+1)\ln 3k]/\ln ((3k+1)(6k+1)\ln n+(6k+1)\ln 3k)}=2^{o(\log n)}. 
\end{align*}
For any sequence~$\mathbf{c}\in\{0,1\}^n$, let 
\begin{align*}
    \mathcal{P}(\mathbf{c})=\{p: p| |M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))| \text{ for some $\mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}$}\} 
\end{align*}
be the set of all divisors of the numbers~$\{|M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))|: \mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}\}$. Since~$|B_k(\mathbf{c})|\le \binom{n}{k}^22^{k} \le 2n^{2k}$, we have that
\begin{align*}
    |\mathcal{P}(\mathbf{c})|\le& 2n^{2k}2^{o(\log n)}\\=&2^{2k\log n +o(\log n)}.
\end{align*}
Therefore, there exists a number~$p(\mathbf{c})\in [1,2^{2k\log n +o(\log n)}]$

such that~$p(\mathbf{c}) \centernot | |M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))|$ for all~$\mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}$. 
Hence, if~$M(f(\mathbbold{1}_{sync}(\mathbf{c}')))\equiv M(f(\mathbbold{1}_{sync}(\mathbf{c})))\bmod p(\mathbf{c})$ and~$\mathbf{c}'\in B_k(\mathbf{c})$, we have that~$p(\mathbf{c})||M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))|$ and thus~$\mathbf{c}'=\mathbf{c}$. 
This completes the proof of Lemma~\ref{lemma:protectingpattern}.

The function~$\mathcal{E}$ is given by
\begin{align*}
    \mathcal{E}(\mathbf{c}) = (T(\mathbf{c}),R'(\mathbf{c}),R''(\mathbf{c})).
\end{align*}
where 
\begin{align*}
   R'(\mathbf{c})&=( M(f(\mathbbold{1}_{sync}(T(\mathbf{c})))) \bmod p(T(\mathbf{c})),p(T(\mathbf{c})),Hash_k(T(\mathbf{c}))), \text{ and }\\
   R''(\mathbf{c})&=Rep_{k+1}(H(R'(\mathbf{c}))).
\end{align*}
Here~$M(\mathbf{v})$ is the function defined in Eq.~\eqref{equation:Mfunction} and~$Rep_{k+1}(H(R'(\mathbf{c})))$ is the~$k+1$-fold repetition of the bits in~$H(R'(\mathbf{c}))$ (See Lemma~\ref{lemma:hash} for definition of function~$H(\mathbf{c})$). The function~$Hash_k(\mathbf{c})$ is defined in Eq.~\eqref{equation:hashk} and the function~$T(\mathbf{c})$ is defined in Lemma~\ref{lemma:transformation}.

Therefore, we need to consider four cases in total. Let~$\mathbf{d}'$ be the subsequence of~$\mathbf{c}$ after a single deletion.





\begin{enumerate}
\item

We now prove~$(2)$ by contradiction. Supposed on the contrary, there exist~$i_1,i_2\in (p_j,p_{j+1}]$ such that~$i_1<i_2$ and
\begin{align*}
    (|S^c_1\cap[i_1,n]|-|S^c_2\cap[i_1,n]|)(|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|)<0
\end{align*}
By symmetry it can be assumed that~$|S^c_1\cap[i_1,n]|-|S^c_2\cap[i_1,n]=-1$ and~$|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|=1$. Note that~$|S^c_1|=|S^c_2|$ and there exists a one-to-one correspondence between the elements in~$S^c_1$ and the elements in~$S^c_2$. Hence from~$|S^c_1\cap[i_1,n]|-|S^c_2\cap[i_1,n]=-1$, there exist two integers~$x\in S^c_1\cap[i_1-1,n]$
and~$y\in S^c_2\cap[i_1,n]$ such that the two~$1$ entries~$c_x$ and~$c'_y$ are in the same location after deletions, i.e.,~$x-|\boldsymbol{\delta}\cap[1,x-1]|=y-|\boldsymbol{\delta}'\cap[1,y-1]|$. Therefore, we have that
\begin{align*}
    i_1-|\boldsymbol{\delta}\cap[1,i_1-1]|>&i_1-1-|\boldsymbol{\delta}\cap[1,i_1-1]|\\
    \ge&x-|\boldsymbol{\delta}\cap[1,x-1]|\\
    =&y-|\boldsymbol{\delta}'\cap[1,y-1]|\\
    \ge& i_1-|\boldsymbol{\delta}'\cap[1,i_1-1]|,
\end{align*}
which implies that
\begin{align} |\boldsymbol{\delta}\cap[1,i_1-1]|<|\boldsymbol{\delta}'\cap[1,i_1-1]|.
\end{align}
 Similarly, from~$|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|=1$ we have that
\begin{align} |\boldsymbol{\delta}\cap[1,i_2-1]|>|\boldsymbol{\delta}'\cap[1,i_2-1]| .   
\end{align}
Eq.~\eqref{equation:contradiction1} and Eq.~\eqref{equation:contradiction2} implies that
\begin{align} |\boldsymbol{\delta}\cap[1,i_2-1]|-|\boldsymbol{\delta}\cap[1,i_1-1]|\ge &
|\boldsymbol{\delta}'\cap[1,i_2-1]|+1-|\boldsymbol{\delta}'\cap[1,i_1-1]|+1\nonumber\\
\ge & 2.
\end{align}
However, since~$i_1,i_2\in (p_j,p_{j+1}]$, we have that~$|\boldsymbol{\delta}\cap[1,i_1]|=|\boldsymbol{\delta}\cap[1,i_2-1]|$ and~$|\boldsymbol{\delta}'\cap[1,i_1]|=|\boldsymbol{\delta}'\cap[1,i_2-1]|$,
which implies that
\begin{align*}
   |\boldsymbol{\delta}\cap[1,i_2-1]|-|\boldsymbol{\delta}\cap[1,i_1-1]|\le
   &|\boldsymbol{\delta}\cap[1,i_2-1]|-|\boldsymbol{\delta}\cap[1,i_1]|+1\\
   =&1.
\end{align*}
contradicting to Eq.~\eqref{equation:contradiction}. Hence there do not exist different integers~$i_1,i_2\in (p_j,p_{j+1}]$ such that
\begin{align*}
    (|S^c_1\cap[i_1,n]|-|S^c_2\cap[i_1,n]|)(|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|)<0.
\end{align*}
Hence~$(2)$ is proved.

Supposed on the contrary, there exist~$i_1,i_2\in (p_j,p_{j+1}]$ such that~$i_1<i_2$ and
\begin{align*}
    (|S^c_1\cap[i_1,n]|-|S^c_2\cap[i_1,n]|)(|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|)<0
\end{align*}

Similarly, from~$|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|=1$ we have that
\begin{align} |\boldsymbol{\delta}\cap[1,i_2-1]|>|\boldsymbol{\delta}'\cap[1,i_2-1]| .   
\end{align}

However, since~$i_1,i_2\in (p_j,p_{j+1}]$, we have that~$|\boldsymbol{\delta}\cap[1,i_1]|=|\boldsymbol{\delta}\cap[1,i_2-1]|$ and~$|\boldsymbol{\delta}'\cap[1,i_1]|=|\boldsymbol{\delta}'\cap[1,i_2-1]|$,
which implies that
\begin{align*}
   |\boldsymbol{\delta}\cap[1,i_2-1]|-|\boldsymbol{\delta}\cap[1,i_1-1]|\le
   &|\boldsymbol{\delta}\cap[1,i_2-1]|-|\boldsymbol{\delta}\cap[1,i_1]|+1\\
   =&1.
\end{align*}
contradicting to Eq.~\eqref{equation:contradiction}. Hence there do not exist different integers~$i_1,i_2\in (p_j,p_{j+1}]$ such that
\begin{align*}
    (|S^c_1\cap[i_1,n]|-|S^c_2\cap[i_1,n]|)(|S^c_1\cap[i_2,n]|-|S^c_2\cap[i_2,n]|)<0.
\end{align*}
Hence~$(2)$ is proved.

Denote
\begin{align*}
s_i\triangleq |S_1\cap[i,n]|-|S_2\cap[i,n]|+|S^c_1\cap[i,n]|-|S^c_2\cap[i,n]|
\end{align*}

Let~$\mathbf{x}=(x_0,\ldots,x_{6k})\in \{-1,1\}^{6k+1}$ be a vector defined by
\begin{align*}
x_i &= \begin{cases}
-1, &\text{if~$s_j<0$ for some~$j\in (p_i,p_{i+1}]$}\\
1,&\text{else.}\\
\end{cases}.
\end{align*}
Then from Eq.~\eqref{equation:difference} we have that
\begin{align} \mathbf{c} \cdot \mathbf{m}^{(e)}- \mathbf{c}' \cdot  \mathbf{m}^{(e)}= \sum^{6k}_{j=0}(\sum^{p_{j+1}}_{i=p_{j}+1}|s_i|i^e)x_j
\end{align}

Let~$A$ be a~$6k+1\times 6k+1$ matrix with entries defined by~$A_{e,j}=\sum^{p_{j}}_{i=p_{j-1}+1}|s_i|i^{e-1}$ for~$e,j\in\{1,\ldots,6k+1\}$.
If~$\mathbf{c} \cdot \mathbf{m}^{(e)}= \mathbf{c}' \cdot  \mathbf{m}^{(e)}$ for~$e\in [0,6k]$, we have the following linear equation
\begin{align} A\boldsymbol{x}=\begin{bmatrix}
\sum^{p_{1}}_{i=p_{0}+1}|s_i|i^0 &\ldots & \sum^{p_{6k+1}}_{i=p_{6k}+1}|s_i|i^0\\
\vdots &\ddots & \vdots\\
\sum^{p_{1}}_{i=p_{0}+1}|s_i|i^{6k} &\ldots & \sum^{p_{6k+1}}_{i=p_{6k}+1}|s_i|i^{6k}
\end{bmatrix}
\begin{bmatrix}
x_0\\
\vdots\\
x_{6k}\\
\end{bmatrix}
=0
\end{align}

We show that this is impossible unless~$A$ is a zero matrix. Suppose on the contrary that~$A$ is nonzero, let~$j_1<\ldots <j_Q$ be the indices of all nonzero columns of~$A$. Let~$B$ be a submatrix of~$A$, obtained by choosing the intersection of the first~$Q$ rows and columns with indices~$j_1,\ldots,j_Q$. Then we have that
\begin{align} B\boldsymbol{x}'=\begin{bmatrix}
\sum^{p_{j_1}}_{i=p_{j_1-1}+1}|s_i|i^0 &\ldots & \sum^{p_{j_Q}}_{i=p_{j_{Q-1}}+1}|s_i|i^0\\
\vdots &\ddots & \vdots\\
\sum^{p_{j_1}}_{i=p_{j_1-1}+1}|s_i|i^{Q-1} &\ldots & \sum^{p_{j_Q}}_{i=p_{j_{Q-1}}+1}|s_i|i^{Q-1}
\end{bmatrix}
\begin{bmatrix}
x_0\\
\vdots\\
x_{Q-1}\\
\end{bmatrix}
=0
\end{align}
By the multi-linearity of the determinant, 
\begin{align}
\det(B)=&\sum_{i_1\in (p_{j_1-1},p_{j_1}],\ldots,i_M\in (p_{j_Q-1},p_{j_Q}]}\det \begin{pmatrix} |s_{i_1}|i^0_1&\ldots&|s_{i_Q}|i^0_Q\\ \vdots&\ddots&\vdots\\ |s_{i_1}|i_1^{Q-1}&|s_{i_Q}|\ldots&i_Q^{Q-1} \end{pmatrix}\nonumber\\
=&\sum_{i_1\in (p_{j_1-1},p_{j_1}],\ldots,i_Q\in (p_{j_{Q-1}},p_{j_Q}]}[\prod^Q_{q=1} |s_{i_q}| \prod_{1\le m<\ell \le Q}(i_{\ell}-i_{m})]
\end{align}
is positive since~$i_{\ell}>i_{m}$ for~$m>\ell$
and for~$i_1\in (p_{j_1-1},p_{j_1}],\ldots,i_Q\in (p_{j_Q-1},p_{j_Q}]$. Note that all the columns of~$B$ are nonzero. 
Therefore, the linear equation~$B\boldsymbol{x}'=0$ does not have nonzero solutions, contradicting to the fact that~$\boldsymbol{x}'\in\{-1,1\}^Q$.

Suppose on the contrary that~$A$ is nonzero, let~$j_1<\ldots <j_Q$ be the indices of all nonzero columns of~$A$. Let~$B$ be a submatrix of~$A$, obtained by choosing the intersection of the first~$Q$ rows and columns with indices~$j_1,\ldots,j_Q$. Then we have that
\begin{align} B\boldsymbol{x}'=\begin{bmatrix}
\sum^{p_{j_1}}_{i=p_{j_1-1}+1}|s_i|i^0 &\ldots & \sum^{p_{j_Q}}_{i=p_{j_{Q-1}}+1}|s_i|i^0\\
\vdots &\ddots & \vdots\\
\sum^{p_{j_1}}_{i=p_{j_1-1}+1}|s_i|i^{Q-1} &\ldots & \sum^{p_{j_Q}}_{i=p_{j_{Q-1}}+1}|s_i|i^{Q-1}
\end{bmatrix}
\begin{bmatrix}
x_0\\
\vdots\\
x_{Q-1}\\
\end{bmatrix}
=0
\end{align}

Hence~$A$ is a zero matrix, meaning that
\begin{align*}
&|S_1\cap[i,n]|-|S_2\cap[i,n]|+|S^c_1\cap[i,n]|-|S^c_2\cap[i,n]|\\
=&|\boldsymbol{\Delta}\cap [i,n]|-|\boldsymbol{\Delta}'\cap [i,n]|=0
\end{align*}
for~$i\in\{1,\ldots,n\}$. This implies~$\boldsymbol{\Delta}=\boldsymbol{\Delta}'$ and thus~$\mathbf{c}=\mathbf{c}'$. Hence Proposition~\ref{lemma:vtextension} is proved.

According to Lemma~\ref{lemma:numberofdivisors}, the number of divisors of~$|M(f(\mathbbold{1}_{sync}(\mathbf{c})))-M(f(\mathbbold{1}_{sync}(\mathbf{c}')))|$ is upper bounded by
\begin{align*}
2^{2[(3k+1)(6k+1)\ln n+(6k+1)\ln 3k]/\ln ((3k+1)(6k+1)\ln n+(6k+1)\ln 3k)}=2^{o(\log n)}. 
\end{align*}

For any sequence~$\mathbf{c}\in\{0,1\}^n$, let 
\begin{align*}
    \mathcal{P}(\mathbf{c})=\{p: p| |M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))| \text{ for some $\mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}$}\} 
\end{align*}
be the set of all divisors of the numbers~$\{|M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))|: \mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}\}$.

Since~$|B_k(\mathbf{c})|\le \binom{n}{k}^22^{k} \le 2n^{2k}$, we have that
\begin{align*}
    |\mathcal{P}(\mathbf{c})|\le& 2n^{2k}2^{o(\log n)}\\=&2^{2k\log n +o(\log n)}.
\end{align*}
Therefore, there exists a number~$p(\mathbf{c})\in [1,2^{2k\log n +o(\log n)}]$

such that~$p(\mathbf{c}) \centernot | |M(f(\mathbbold{1}_{sync}(\mathbf{c}')))-M(f(\mathbbold{1}_{sync}(\mathbf{c})))|$ for all~$\mathbf{c}'\in B_k(\mathbf{c})\backslash \{\mathbf{c}\}$.

For a sequence~$\mathbf{c}\in\{0,1\}^n$, the encoding procedure for computing~$T_1(\mathbf{c})$ is as follows.
\begin{enumerate}
    \item

\textbf{Step 4:}
    If~$i\le n'$, let~$i=i+1$ and go to Step~$1$.
    Else output~$T_1(\mathbf{c})$.

We now give the following decoding procedure that recovers~$\mathbf{c}$ from~$T_1(\mathbf{c})$.
\begin{enumerate}
    \item

Given~$\mathbf{c}\in\{0,1\}^{3k+\lceil \log k\rceil+4}$, the encoding procedure for computing~$T_2(\mathbf{c})$ is given as follows.
\begin{enumerate}
    \item

\textbf{Step 2:}
    If~$i\le n'$, let~$i=i+1$ and go to Step~$1$.
    Else output~$T_2(\mathbf{c})$.

The length of the sequence~$T_2(\mathbf{c})$ keeps constant and is
\begin{align*}
    3k+\lceil \log k\rceil+4+1-\lceil \log k \rceil -5+\lceil \log k\rceil+3=3k+\lceil \log k\rceil+3.
\end{align*}
The integer~$n'$ is defined such that~$(T_2(\mathbf{c})_{n'+1},\ldots,T_2(\mathbf{c})_{3k+\lceil \log k\rceil+3})$ are appended bits and~$(T_2(\mathbf{c})_{1},$ $\ldots,T_2(\mathbf{c})_{n'})$ are the remaining bits in~$T_2(\mathbf{c})$ after deleting~$(T_2(\mathbf{c})_i,\ldots,T_2(\mathbf{c})_{i+\lceil \log k \rceil +4})$. Note that~$T_2(\mathbf{c})_{n'+1}=0$. Hence if~$(T_2(\mathbf{c})_i,\ldots,$ $T_2(\mathbf{c})_{i+\lceil \log k\rceil+4})=\boldsymbol{1}^{\lceil \log k\rceil+5}$, then~$i+\lceil \log k\rceil+4\le n'$ and thus~$T_2(\mathbf{c})_{n'+1}$ is not deleted.

\textbf{Step 2:}
    If~$i\le n'$, let~$i=i+1$ and go to Step~$1$.
    Else output~$T(\mathbf{c})$.

Finally we present the following decoding procedure that recovers~$\mathbf{c}$ from~$T(\mathbf{c})$.
\begin{enumerate}
    \item
